
public class Comparetwocharacter {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char ch1='b';
		char ch2='d';
		if(ch1<ch2) {
			System.out.println(ch1 + " comes first then " + ch2);
		}else if(ch2<ch1) {
			System.out.println(ch2 + " comes first then " + ch1);
		}else {
			System.out.println("Both are same character");
		}

	}

}
